import assert from 'node:assert/strict';
import {createHash} from 'node:crypto';
import {writeFile} from 'node:fs/promises';
import {createRequire} from 'node:module';
const root=new URL('../',import.meta.url);
const baseline=await import(new URL('variants/baseline/lib/index.js',root));
const candidate=await import(new URL('variants/candidate/lib/index.js',root));
const winBase=await import(new URL('variants/baseline/lib/resource-win32.js',root));
const winCandidate=await import(new URL('variants/candidate/lib/resource-win32.js',root));
const URI=createRequire(new URL('variants/baseline/lib/index.js',root))('urijs');
const seeds=[1,19,42,123456789,0x12345678,0x9e3779b9,0xdeadbeef,0x7fffffff];
let state,paths=0,documents=0,pathErrors=0,htmlErrors=0;
const random=()=>{state^=state<<13;state^=state>>>17;state^=state<<5;return(state>>>0)/4294967296;};
const pick=a=>a[Math.floor(random()*a.length)];
const segments=['','a','b.html','%2e','%2E%2e','.%2e','%2e.','.','..','...','%252e%252e','%2F','%5c','%3a','%ZZ','%C0%AF','a:b','x&y','日本語','😀','a\\b','x\0y','\uD800','..x','x y','%EF%BC%8E'];
const capture=fn=>{try{return {value:fn()};}catch(e){return {error:e.name,message:e.message};}};
const checksum=createHash('sha256');
const sources=['a[href]','style','.css-target'];
const css=['.x{color:red}','.x{background:url(a.png)}','@import "x.css";',
 '.x{background:URL( \' a.png \' )}','/* url(skip) */','.x{content:"<b>&amp;"}',
 '.x{background:url(data:image/png;base64,abc)}','url(  )','url("a\n b")','url( /*x*/ icon.png )','<b>text</b>','<!-- -->','&amp;','@import url(x);','url(url)','url(\'x"y\')',''];
async function process(api,input){
 const events=[];const base=api.lifeCycle.defaultLifeCycle();
 const options=api.options.defaultDownloadOptions({...base,
  linkRedirect:[...base.linkRedirect,async url=>input.drop&&url.includes('a.png')?undefined:url],
  processBeforeDownload:[async(resource,_element,parent)=>{
   events.push(resource.rawUrl);
   if(input.mutate===1)parent.meta.doc('style,.css-target').text('hook mutation');
   if(input.mutate===2)parent.meta.doc('style').append('/* hook */');
   if(input.mutate===3)parent.meta.doc('style').empty();
   resource.replacePath=input.rewrite?'saved/'+resource.rawUrl:resource.rawUrl;
   return resource;
  }],
  sources:[{selector:'style',type:4},{selector:'.css-target',type:4},{selector:'*[style]',attr:'style',type:4}]
 });
 const pipeline=new api.downloader.PipelineExecutorImpl(options,options.req,options);
 const parent={...api.resource.createResource({type:2,depth:0,url:'https://example.test/docs/index.html',refUrl:'https://example.test/',localRoot:'/out'}),body:input.html};
 const resources=[];
 try{
  await pipeline.processAfterDownload(parent,value=>resources.push(...Array.isArray(value)?value:[value]));
  return {html:parent.meta.doc.html(),events,resources:resources.map(x=>[x.url,x.savePath,x.replacePath])};
 }catch(e){return {error:e.name,message:e.message,events};}
}
try{
 for(const seed of seeds){
  state=seed;
  for(let i=0;i<10000;i++){
   const url=pick(['https://example.test/','http://EXAMPLE.test:8080/','https://[::1]/'])+Array.from({length:1+Math.floor(random()*8)},()=>pick(segments)).join('/')+pick(['','/','?b=2&a=1','#hash','?x=%ZZ']);
   const isHtml=random()<.5,keepSearch=random()<.5;
   for(const [a,b] of [[baseline.resource,candidate.resource],[winBase,winCandidate]]){
    const f=api=>capture(()=>api.generateSavePath(URI(url),isHtml,keepSearch));
    const before=f(a),after=f(b);assert.deepEqual(after,before,JSON.stringify({seed,i,url,isHtml,keepSearch}));
    if(before.error)pathErrors++;paths++;checksum.update(JSON.stringify(before));
   }
  }
  for(let i=0;i<1000;i++){
   const content=Array.from({length:1+Math.floor(random()*6)},()=>pick(css)).join(pick(['','\n',' ' ]));
   const html=pick(['<style>'+content+'</style>','<svg><style>'+content+'</style></svg>','<div class="css-target">'+content+'</div>',
    '<style>'+content+'</style><style>'+content+'</style>','<div style="'+content.replaceAll('"','&quot;')+'"></div>']);
   const input={html,mutate:Math.floor(random()*4),rewrite:random()<.5,drop:random()<.3};
   const before=await process(baseline,input),after=await process(candidate,input);
   assert.deepEqual(after,before,JSON.stringify({seed,i,...input}));
   documents++;if(before.error)htmlErrors++;checksum.update(JSON.stringify(after));
  }
  process.stderr?.write?.('');
 }
 const report={passed:true,seeds,pathComparisons:paths,pathErrors,htmlComparisons:documents,htmlErrors,checksum:checksum.digest('hex'),windowsScope:'HTTP save paths through node:path.win32, not native Windows filesystem execution.'};
 await writeFile(new URL('logs/fuzz.json',root),JSON.stringify(report,null,2));console.log(JSON.stringify(report));
}catch(error){await writeFile(new URL('logs/fuzz-failure.txt',root),error.stack+'\n'+error.message);throw error;}
